WITH flattened AS (SELECT id, service, log_ts, level, latency_ms, status_code, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, v) SELECT service, level, latency_ms, CASE WHEN service RLIKE '^(search|checkout)$' THEN 'PRIORITY' WHEN service RLIKE '^(auth|billing)$' THEN 'EXTENDED' ELSE 'CORE' END AS service_zone FROM flattened ORDER BY service_zone NULLS FIRST, latency_ms
